<script>const sync=()=>{const number=document.querySelector('[name=registration_mode]:checked')?.value;document.querySelector('[data-typed-number]').hidden=number!=='typed';const parent=document.querySelector('[name=parent_mode]:checked')?.value;document.querySelector('[data-parent-new]').hidden=parent!=='new';document.querySelector('[data-parent-existing]').hidden=parent!=='existing'};document.querySelectorAll('[data-number-mode],[data-parent-mode]').forEach(x=>x.addEventListener('change',sync));document.querySelector('[data-arm]').addEventListener('change',e=>{if(e.target.value)location.href='{{ route('students.create') }}?class_arm_id='+encodeURIComponent(e.target.value)});sync()</script>
